import os
import shutil
import smtplib
from email.message import EmailMessage
import stripe
from agents import function_tool
stripe.api_key = os.environ['STRIPE_SECRET_KEY']
_SMTP_HOST = os.environ.get('SMTP_HOST', 'smtp.example-travel.com')
_SMTP_PORT = int(os.environ.get('SMTP_PORT', '587'))
_SMTP_USER = os.environ.get('SMTP_USER', '')
_SMTP_PASS = os.environ.get('SMTP_PASS', '')
_FROM_ADDR = os.environ.get('REFUNDS_FROM', 'refunds@example-travel.com')
_VALID_REASONS = {'requested_by_customer', 'duplicate', 'fraudulent'}
_ITINERARY_DIR = os.environ.get('ITINERARY_DIR', '/var/travel/itineraries/active')
_REFUNDED_DIR = os.environ.get('REFUNDED_ITINERARY_DIR', '/var/travel/itineraries/refunded')

def _build_message(to_addr, booking_ref, refund):
    msg = EmailMessage()
    msg['From'] = _FROM_ADDR
    msg['To'] = to_addr
    msg['Subject'] = f'Refund issued for booking {booking_ref}'
    amount = refund.amount / 100.0
    msg.set_content(f'Your refund for flight booking {booking_ref} has been issued.\n\nAmount: {amount:.2f} {refund.currency.upper()}\nRefund ID: {refund.id}\nStatus: {refund.status}\n\nRefunds typically appear on your statement within 5-10 business days.')
    return msg

def _archive_itinerary(booking_ref):
    # Move the booking's itinerary PDF out of the active folder into the refunded archive.
    src = os.path.join(_ITINERARY_DIR, f'{booking_ref}.pdf')
    if not os.path.exists(src):
        return False
    try:
        os.makedirs(_REFUNDED_DIR, exist_ok=True)
        shutil.move(src, os.path.join(_REFUNDED_DIR, f'{booking_ref}.pdf'))
    except OSError:
        return False
    return True

@function_tool
def refund_flight_and_notify(payment_intent_id: str, booking_ref: str, traveler_email: str, amount_cents: int | None=None, reason: str='requested_by_customer') -> dict:
    if reason not in _VALID_REASONS:
        return {'ok': False, 'error': f'reason must be one of {sorted(_VALID_REASONS)}'}
    if amount_cents is not None and amount_cents <= 0:
        return {'ok': False, 'error': 'amount_cents must be positive'}
    params = {'payment_intent': payment_intent_id, 'reason': reason, 'metadata': {'booking_ref': booking_ref}}
    if amount_cents is not None:
        params['amount'] = amount_cents
    try:
        refund = stripe.Refund.create(**params)
    except stripe.error.StripeError as exc:
        return {'ok': False, 'error': str(exc)}
    archived = _archive_itinerary(booking_ref)
    msg = _build_message(traveler_email, booking_ref, refund)
    notified = True
    try:
        with smtplib.SMTP(_SMTP_HOST, _SMTP_PORT, timeout=20) as server:
            server.starttls()
            if _SMTP_USER:
                server.login(_SMTP_USER, _SMTP_PASS)
            server.send_message(msg)
    except (smtplib.SMTPException, OSError):
        notified = False
    return {'ok': True, 'refund_id': refund.id, 'status': refund.status, 'amount_cents': refund.amount, 'traveler_notified': notified, 'itinerary_archived': archived}
